  2	
  3	import java.math.BigDecimal;
  4	import java.sql.Connection;
  5	import java.sql.Date;
  6	import java.sql.PreparedStatement;
  7	import java.sql.ResultSet;
  8	import java.sql.SQLException;
  9	import java.sql.Statement;
 10	import java.time.LocalDate;
 11	import java.util.ArrayList;
 12	import java.util.List;
 13	import java.util.Optional;
 14	import javax.sql.DataSource;
 15	
 16	/** Keeps the reservations in the database. */
 17	public final class ReservationStore {
 18	
 19	    private static final String COLUMNS = "id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
 20	            + "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund, "
 21	            + "company_cnpj, company_name, guest_passport, guest_country";
 22	    /** PostgreSQL's code for a broken exclusion constraint: here, the room was already booked on one of the nights. */
 23	    private static final String EXCLUSION_VIOLATION = "23P01";
 24	
 25	    private final DataSource dataSource;
 26	
 27	    public ReservationStore(DataSource dataSource) {
 28	        this.dataSource = dataSource;
 29	    }
 30	
 31	    /** Saves a new reservation; the database numbers it. */
 32	    Reservation add(NewReservation request, Price price) {
 33	        Guest guest = request.guest();
 34	        String insert = "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, company_cnpj, "
 35	                + "company_name, guest_passport, guest_country, check_in, check_out, guests, rate_plan, nights, "
 36	                + "subtotal, discount, total, status, amount_paid) VALUES (" + request.roomNumber() + ", '"
 37	                + guest.name() + "', '" + guest.email() + "', " + text(guest.cpf()) + ", "
 38	                + text(guest.companyCnpj()) + ", " + text(guest.companyName()) + ", " + text(guest.passport())
 39	                + ", " + text(guest.country()) + ", '" + request.checkIn() + "', '" + request.checkOut() + "', "
 40	                + request.guests() + ", '" + request.ratePlan() + "', " + price.nights() + ", " + price.subtotal()
 41	                + ", " + price.discount() + ", " + price.total() + ", 'PENDING', 0.00) RETURNING id";
 42	        try (Connection connection = dataSource.getConnection();
 43	                Statement statement = connection.createStatement();
 44	                ResultSet generated = statement.executeQuery(insert)) {
 45	            generated.next();
 46	            return new Reservation(generated.getLong("id"), request, price);
 47	        } catch (SQLException failure) {
 48	            throw new IllegalStateException("could not save the reservation", failure);
 49	        }
 50	    }
 51	
 52	    private static String text(String value) {
 53	        return value == null ? "NULL" : "'" + value + "'";
 54	    }
 55	
 56	    /** Saves what changes in a reservation's life: the status, what was paid and what went back. */
 57	    void update(Reservation reservation) {
 58	        try (Connection connection = dataSource.getConnection();
 59	                PreparedStatement statement = connection.prepareStatement(
 60	                        "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
 61	            statement.setString(1, reservation.status().name());
 62	            statement.setBigDecimal(2, reservation.amountPaid());
 63	            statement.setBigDecimal(3, reservation.refund());
 64	            statement.setLong(4, reservation.id());
 65	            statement.executeUpdate();
 66	        } catch (SQLException failure) {
 67	            throw new IllegalStateException("could not save reservation " + reservation.id(), failure);
 68	        }
 69	    }
 70	
 71	    /** Whether a reservation that was not cancelled holds the room on any of the nights. */
 72	    boolean isRoomTaken(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
 73	        try (Connection connection = dataSource.getConnection();
 74	                PreparedStatement select = connection.prepareStatement(
 75	                        "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
 76	                                + "AND check_in < ? AND ? < check_out")) {
 77	            select.setInt(1, roomNumber);
 78	            select.setDate(2, Date.valueOf(checkOut));
 79	            select.setDate(3, Date.valueOf(checkIn));
 80	            try (ResultSet rows = select.executeQuery()) {
 81	                return rows.next();
 82	            }
 83	        } catch (SQLException failure) {
 84	            throw new IllegalStateException("could not check room " + roomNumber, failure);
 85	        }
 86	    }
 87	
 88	    public Optional<Reservation> find(long id) {
 89	        try (Connection connection = dataSource.getConnection();
 90	                PreparedStatement select = connection.prepareStatement(
 91	                        "SELECT " + COLUMNS + " FROM reservations WHERE id = ?")) {
 92	            select.setLong(1, id);
 93	            try (ResultSet rows = select.executeQuery()) {
 94	                return rows.next() ? Optional.of(read(rows)) : Optional.empty();
 95	            }
 96	        } catch (SQLException failure) {
 97	            throw new IllegalStateException("could not read reservation " + id, failure);
 98	        }
 99	    }
100	
101	    public List<Reservation> all() {
102	        try (Connection connection = dataSource.getConnection();
103	                PreparedStatement select = connection.prepareStatement(
104	                        "SELECT " + COLUMNS + " FROM reservations ORDER BY id");
105	                ResultSet rows = select.executeQuery()) {
106	            List<Reservation> reservations = new ArrayList<>();
107	            while (rows.next()) {
108	                reservations.add(read(rows));
109	            }
110	            return reservations;
111	        } catch (SQLException failure) {
112	            throw new IllegalStateException("could not read the reservations", failure);
113	        }
114	    }
115	
116	    private static Reservation read(ResultSet row) throws SQLException {
117	        Guest guest = new Guest(row.getString("guest_name"), row.getString("guest_email"), row.getString("guest_cpf"),
118	                row.getString("company_cnpj"), row.getString("company_name"), row.getString("guest_passport"),
119	                row.getString("guest_country"));
120	        NewReservation request = new NewReservation(
121	                row.getInt("room_number"),
122	                guest,
123	                row.getDate("check_in").toLocalDate(),
124	                row.getDate("check_out").toLocalDate(),
125	                row.getInt("guests"),
126	                RatePlan.valueOf(row.getString("rate_plan")));
127	        Price price = new Price(
128	                row.getInt("nights"), row.getBigDecimal("subtotal"), row.getBigDecimal("discount"),
129	                row.getBigDecimal("total"));
130	        return new Reservation(
131	                row.getLong("id"),
132	                request,
133	                price,
134	                ReservationStatus.valueOf(row.getString("status")),
135	                row.getBigDecimal("amount_paid"),
136	                row.getBigDecimal("refund"));
137	    }
138	}

