 78	            select.setDate(2, Date.valueOf(checkOut));
 79	            select.setDate(3, Date.valueOf(checkIn));
 80	            try (ResultSet rows = select.executeQuery()) {
 81	                return rows.next();
 82	            }
 83	        } catch (SQLException failure) {
 84	            throw new IllegalStateException("could not check room " + roomNumber, failure);
 85	        }
 86	    }
