 88	    public Optional<Reservation> find(long id) {
 89	        try (Connection connection = dataSource.getConnection();
 90	                PreparedStatement select = connection.prepareStatement(
 91	                        "SELECT " + COLUMNS + " FROM reservations WHERE id = ?")) {
 92	            select.setLong(1, id);
 93	            try (ResultSet rows = select.executeQuery()) {
 94	                return rows.next() ? Optional.of(read(rows)) : Optional.empty();
 95	            }
 96	        } catch (SQLException failure) {
 97	            throw new IllegalStateException("could not read reservation " + id, failure);
 98	        }
 99	    }
100	
101	    public List<Reservation> all() {
102	        try (Connection connection = dataSource.getConnection();
103	                PreparedStatement select = connection.prepareStatement(
104	                        "SELECT " + COLUMNS + " FROM reservations ORDER BY id");
105	                ResultSet rows = select.executeQuery()) {
106	            List<Reservation> reservations = new ArrayList<>();
107	            while (rows.next()) {
108	                reservations.add(read(rows));
109	            }
110	            return reservations;
111	        } catch (SQLException failure) {
112	            throw new IllegalStateException("could not read the reservations", failure);
113	        }
114	    }
